code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for i in range(h):
        for j in range(w):
            color = grid[i][j]
            if color == background or (i, j) in seen:
                continue
            stack = [(i, j)]
            seen.add((i, j))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            if len(cells) >= 2:
                components.append((color, min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            color = grid[i][j]
            # Reclassify isolated pixels and small contaminant colors when they
            # lie inside the extent of a coherent object.
            same = [c for c,r0,r1,c0,c1 in components if r0 <= i <= r1 and c0 <= j <= c1]
            if same:
                out[i][j] = same[0]
            elif color != background and not any(c == color and r0 <= i <= r1 and c0 <= j <= c1 for c,r0,r1,c0,c1 in components):
                out[i][j] = background
    return out
'''
